import "server-only";

import { readFile } from "node:fs/promises";
import path from "node:path";

import { frontFaceName, nameKey } from "@/lib/cards/names";
import type { Card, TokenCard } from "@/lib/cards/types";

export interface CardDb {
  cards: Card[];
  tokens: TokenCard[];
  byId: Map<string, Card>;
  /** Keyed by `nameKey` of both the full name and the front face name. */
  byName: Map<string, Card>;
}

let db: Promise<CardDb> | null = null;

/** Loads data/cards.json once per server instance (generated by scripts/build-card-db.ts). */
export function getCardDb(): Promise<CardDb> {
  db ??= load().catch((err) => {
    db = null;
    throw err;
  });
  return db;
}

async function readData<T>(file: string): Promise<T> {
  return JSON.parse(await readFile(path.join(process.cwd(), "data", file), "utf8")) as T;
}

async function load(): Promise<CardDb> {
  const [cards, tokens] = await Promise.all([readData<Card[]>("cards.json"), readData<TokenCard[]>("tokens.json")]);
  const byId = new Map<string, Card>();
  const byName = new Map<string, Card>();
  for (const card of cards) {
    byId.set(card.id, card);
    byName.set(nameKey(card.name), card);
    const front = nameKey(frontFaceName(card.name));
    if (!byName.has(front)) byName.set(front, card);
  }
  return { cards, tokens, byId, byName };
}

export function findCard(db: CardDb, name: string): Card | undefined {
  return db.byName.get(nameKey(name)) ?? db.byName.get(nameKey(frontFaceName(name)));
}
